    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long length = (long) in.nval;
        long[] x = new long[n], v = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            x[i] = (long) in.nval;
        }
        for (int i = 0; i < n; i++) {
            in.nextToken();
            v[i] = (long) in.nval;
        }
        System.out.println(lastExitTime(length, x, v));
    }
}
